ALTER TABLE command_submissions DROP CONSTRAINT command_submissions_command_name_check;
ALTER TABLE command_submissions ADD CONSTRAINT command_submissions_command_name_check CHECK(command_name IN ('task','pov','poll','help','gh'));
CREATE TABLE command_gh_executions (execution_id TEXT NOT NULL, room_id UUID NOT NULL, submission_id TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('queued','completed','failed')), projection_json JSONB, rendered_text TEXT CHECK(length(rendered_text) <= 4000), failure_kind TEXT, diagnostics_json JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, PRIMARY KEY(room_id,execution_id), UNIQUE(room_id,submission_id), FOREIGN KEY(room_id,submission_id) REFERENCES command_submissions(room_id,submission_id) ON DELETE CASCADE);
CREATE FUNCTION command_gh_execution_acceptance() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.command_name='gh' THEN INSERT INTO command_gh_executions(execution_id,room_id,submission_id,status,diagnostics_json,created_at,updated_at) VALUES(NEW.submission_id || '-gh',NEW.room_id,NEW.submission_id,'queued','[]'::jsonb,NEW.created_at,NEW.created_at); END IF; RETURN NEW; END $$;
CREATE TRIGGER command_gh_execution_acceptance AFTER INSERT ON command_submissions FOR EACH ROW EXECUTE FUNCTION command_gh_execution_acceptance();
